import pandas as pd

def clean(df):
    df = df.copy()
    df['Category'] = df['Category'].replace({'Office Suplies': 'Office Supplies', 'Accesories': 'Accessories'})
    df['Region'] = df['Region'].replace({' East': 'East'})
    df = df.drop_duplicates().reset_index(drop=True)
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    return df.groupby('Category')['Revenue'].sum().to_dict()
